--- a/services/autoscaler/token_bucket.go
+++ b/services/autoscaler/token_bucket.go
@@ -214,7 +214,18 @@ func (tb *TokenBucket) AvailableTokens(...) {
-    // previous logic applied rlimit per pool incorrectly
-    available = min(poolTokens, rlimit)
+    // New: aggregate tokens across compatible pools, then enforce tenant rlimit once
+    aggregated := 0
+    for _, p := range compatiblePools {
+        aggregated += p.Available()
+    }
+    // clamp to smoothing boundary to avoid negative values from concurrent drains
+    if aggregated < 0 {
+        aggregated = 0
+    }
+    available = min(aggregated, tenantRLimit)
